var ArrayList = Java.type('java.util.ArrayList');
var HashSet   = Java.type('java.util.HashSet');

var out  = new ArrayList();
var seen = new HashSet();

function push(v) {
  if (v && !seen.contains(v)) {
    seen.add(v);
    out.add(v);
  }
}

var rawGroups = token.getOtherClaims().get("groups");
if (rawGroups) {
  var arr = rawGroups.toArray();
  for (var i = 0; i < arr.length; i++) {
    var g = String(arr[i]);

    if (["uma_authorization","offline_access","manage-account","view-profile"].indexOf(g) < 0) {

      var bcMatch = g.match(/(?:^|\/).*(bc_[a-z0-9_]+)$/i);
      if (bcMatch) {
        var bcKey = bcMatch[1].toLowerCase();
        var bcLabel = bcMap[bcKey] || null;
        if (bcLabel) {
          push("/business_customer");
          push("/departament_business_customer/" + bcLabel);
        }
      } else {
        push(g);
      }

      var m = g.match(/_(kmbkcb|ptitpc|rnd|rb|finmdl|idsrc|mdlctl|pirm|strdat|digagt|dadm)$/i);
      if (m) {
        var key = m[1].toLowerCase();
        var label = depMap[key] || null;
        if (label) {
          push(label);
          push("/departament/" + label);
        }
      }

      if (g === "ds_lead" || g.indexOf("/ds_lead") >= 0 || g.match(/(^|_)ds_lead$/i)) {
        push("/ds");
        push("/ds/ds_lead");
      }

      if (g === "ds" || g.indexOf("/ds/") === 0 || g.match(/(^|_)ds$/i)) {
        push("/ds");
      }
    }
  }
}

